&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Empathy, patience, kindness, and respect.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Ability to travel to &lt;span class=&quot;TrackChangeTextInsertion TrackedChange SCXW247263435 BCX0&quot;&gt;&lt;span class=&quot;TextRun SCXW247263435 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW247263435 BCX0&quot;&gt;clients’ homes&lt;/span&gt;&lt;/span&gt;&lt;/span&gt; &lt;span class=&quot;TextRun SCXW247263435 BCX0&quot; lang=&quot;EN-US&quot; data-contrast=&quot;none&quot;&gt;&lt;span class=&quot;NormalTextRun SCXW247263435 BCX0&quot;&gt;as assigned.&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
